<?php

declare(strict_types=1);

namespace App\Twig;

use App\Storefront\Brand\BrandContent;
use App\Storefront\Brand\BrandContributorInterface;
use Symfony\Component\DependencyInjection\Attribute\AutowireIterator;
use Symfony\Contracts\Service\ResetInterface;
use Twig\Extension\AbstractExtension;
use Twig\TwigFunction;

/**
 * Exposes storefront_brand(): the identity of the current shop, built from the
 * BrandContributorInterface services (import, project code...).
 *
 * Generated by sylius-starter/core: do not edit.
 */
final class StorefrontBrandExtension extends AbstractExtension implements ResetInterface
{
    private ?BrandContent $content = null;

    /**
     * @param iterable<BrandContributorInterface> $contributors
     */
    public function __construct(
        #[AutowireIterator(BrandContributorInterface::TAG)]
        private readonly iterable $contributors,
    ) {}

    public function getFunctions(): array
    {
        return [
            new TwigFunction('storefront_brand', $this->getBrand(...)),
        ];
    }

    public function getBrand(): BrandContent
    {
        if (null !== $this->content) {
            return $this->content;
        }

        $content = new BrandContent();

        foreach ($this->contributors as $contributor) {
            $content = $contributor->contribute($content);
        }

        return $this->content = $content;
    }

    /**
     * The content depends on the current channel: never keep it across requests.
     */
    public function reset(): void
    {
        $this->content = null;
    }
}
